mockup.css:
.mock-hero-aperture-mask { background: #efe6d6; color: #241c12; display: flex; align-items: center;
  justify-content: center; font-family: "Iowan Old Style", Palatino, Georgia, serif; }
.mock-hero-aperture-mask .arch { position: absolute; inset: 12% 34% 15% 34%;
  border-radius: 50% 50% 0 0 / 62% 62% 0 0; overflow: hidden; }
.mock-hero-aperture-mask .arch::after { content: ""; position: absolute; inset: 0;
  box-shadow: inset 0 0 0 .5cqw rgba(36,28,18,.35); border-radius: inherit; }
.mock-hero-aperture-mask h4 { position: relative; z-index: 2; margin: 0; text-align: center; font-size: 9.5cqw;
  line-height: .92; letter-spacing: -.02em; color: #f6efe1; text-shadow: 0 .4cqw 2cqw rgba(20,12,4,.55); }
.mock-hero-aperture-mask .under { position: absolute; z-index: 3; bottom: 3.5cqw; left: 0; right: 0; text-align: center;
  font-family: "Inter", ui-sans-serif, sans-serif; font-size: 1.7cqw;
  letter-spacing: .16em; text-transform: uppercase; opacity: .7; }
